#!/usr/bin/env bash\n# Scan repository for TODO comments and fail if any are found.\n\n# Directories to ignore (space-separated)\nIGNORE_PATHS=".git node_modules vendor"\n\n# Build grep exclude arguments\nEXCLUDE_ARGS=()\nfor path in $IGNORE_PATHS; do\n  EXCLUDE_ARGS+=(--exclude-dir="$path")\n done\n\n# Search for TODO in all files\nTODO_FILES=$(grep -RIl "TODO" . "${EXCLUDE_ARGS[@]}" || true)\n\nif [ -n "$TODO_FILES" ]; then\n  echo "❌ TODO comments found in the following files:"\n  echo "$TODO_FILES"\n  exit 1\nelse\n  echo "✅ No TODO comments found."\n  exit 0\nfi
